complain if-executable 1password /opt/1Password/1password
complain if-executable brave /usr/bin/brave-browser
complain if-executable chrome /usr/bin/google-chrome-stable
disable optional discord -
complain if-executable element-desktop /usr/bin/element-desktop
complain if-executable firefox /usr/bin/firefox
